package com.arnavgames.tycoon.core.content

import kotlinx.serialization.Serializable

/**
 * The demo store catalogue (content/data/store.json, generated by tools/content/gen_store.py). docs/GDD.md §15.
 * Demo prices are labels only: every "purchase" is simulated and no payment details are ever requested.
 */
@Serializable
data class StoreContent(
    val sections: List<StoreSectionDef>,
    val products: List<ProductDef>,
    val cosmetics: List<CosmeticDef>,
    val config: StoreConfig = StoreConfig(),
    /** Avatars every player can choose; premium ones are cosmetics of kind "avatar". */
    val freeAvatars: List<String> = emptyList(),
) {
    @kotlinx.serialization.Transient val productById = products.associateBy { it.id }
    @kotlinx.serialization.Transient val cosmeticById = cosmetics.associateBy { it.id }

    companion object {
        val EMPTY = StoreContent(emptyList(), emptyList(), emptyList())
    }
}

@Serializable
data class StoreSectionDef(val id: String, val name: String)

@Serializable
data class ProductGrantsDef(
    val bullion: Long = 0,
    val favor: Long = 0,
    /** Hours of ×2 income for every business (extends a running boost). */
    val boostHours: Int = 0,
    val permanentPct: Double = 0.0,
    val slots: Int = 0,
    val offlineHours: Int = 0,
    val vipDays: Int = 0,
    val seasonPass: Int = 0,
    val cosmetic: String? = null,
)

/** demoPrice: a label for the simulated purchase (null = Bullion only). bullionPrice: null = demo only. limit 0 = no limit. */
@Serializable
data class ProductDef(
    val id: String,
    val name: String,
    val description: String,
    val section: String,
    val demoPrice: String? = null,
    val bullionPrice: Long? = null,
    val grants: ProductGrantsDef,
    val limit: Int = 0,
)

@Serializable
data class CosmeticDef(val id: String, val kind: String, val name: String)

@Serializable
data class StoreConfig(
    val maxPermanentPct: Double = 0.3,
    val maxSlots: Int = 3,
    val maxOfflineHours: Int = 8,
    val vipIncomePct: Double = 0.1,
    val vipOfflineHours: Int = 2,
    val vipLadderBullion: Long = 20,
    /** Income bonus of a timed boost (0.25 = +25 %). */
    val boostPct: Double = 0.25,
)
